    public static function followUpBody(string $firstName, string $project, string $senderName): string
    {
        return "Hi {$firstName},\n\nThanks for getting in touch about {$project}. Oakline Trade includes volume pricing from 10 pieces, a dedicated account manager, and white-glove delivery and installation scheduled around your timeline.\n\nCould we book a 15-minute call this week to go through quantities and dates? I'm also happy to send wood and fabric samples beforehand.\n\n{$senderName}, Oakline Home";
    }

